BEGIN;
CREATE TABLE IF NOT EXISTS harvests(id uuid PRIMARY KEY,cycle_id uuid NOT NULL REFERENCES production_cycles(id),harvest_date date NOT NULL,buyer_id uuid REFERENCES business_partners(id),bird_qty integer NOT NULL CHECK(bird_qty>0),total_weight_kg numeric(18,3) NOT NULL CHECK(total_weight_kg>0),actual_price_per_kg numeric(18,2) NOT NULL CHECK(actual_price_per_kg>=0),status varchar(20) NOT NULL DEFAULT 'POSTED' CHECK(status IN('POSTED','VOID')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier_invoices(id uuid PRIMARY KEY,supplier_id uuid NOT NULL REFERENCES business_partners(id),invoice_number varchar(100) NOT NULL,invoice_date date NOT NULL,due_date date,total_amount numeric(18,2) NOT NULL CHECK(total_amount>=0),status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','PARTIAL','PAID','VOID')),UNIQUE(supplier_id,invoice_number));
CREATE TABLE IF NOT EXISTS sales_invoices(id uuid PRIMARY KEY,customer_id uuid NOT NULL REFERENCES business_partners(id),invoice_number varchar(100) NOT NULL UNIQUE,invoice_date date NOT NULL,due_date date,total_amount numeric(18,2) NOT NULL CHECK(total_amount>=0),status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','PARTIAL','PAID','VOID')));
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY,payment_date date NOT NULL,direction varchar(10) NOT NULL CHECK(direction IN('IN','OUT')),amount numeric(18,2) NOT NULL CHECK(amount>0),method varchar(30) NOT NULL,bank_account_id uuid REFERENCES company_bank_accounts(id),reference_number varchar(120) NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_allocations(id uuid PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(id) ON DELETE CASCADE,sales_invoice_id uuid REFERENCES sales_invoices(id),supplier_invoice_id uuid REFERENCES supplier_invoices(id),amount numeric(18,2) NOT NULL CHECK(amount>0),CHECK((sales_invoice_id IS NOT NULL)::int + (supplier_invoice_id IS NOT NULL)::int = 1));
CREATE TABLE IF NOT EXISTS barn_operational_costs(id uuid PRIMARY KEY,cycle_id uuid NOT NULL REFERENCES production_cycles(id),expense_date date NOT NULL,description text NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS barn_maintenance_costs(id uuid PRIMARY KEY,barn_id uuid NOT NULL REFERENCES barns(id),expense_date date NOT NULL,description text NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS global_expenses(id uuid PRIMARY KEY,expense_scope varchar(20) NOT NULL CHECK(expense_scope IN('KANTOR','LUAR_KANTOR')),expense_date date NOT NULL,description text NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>=0),created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
